/*
 * LAKA Soluciones Tecnológicas
 * Dashboard de recursos de servidores · Zabbix / Grafana
 * Autor: Willian Tola | LAKA
 * Marca y presentación: LAKA Soluciones Tecnológicas
 */
// Business Text 6.x: After Content Ready. Datos entregados por el plugin Zabbix.
const root = context.element;
const frames = context.panelData?.series || [];
const end = Number(context.grafana.timeRange.to.valueOf());
const MAX_AGE = 15 * 60 * 1000;
const read = (f, i) => f?.values?.get ? f.values.get(i) : f?.values?.[i];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hosts = new Map();
const host = name => {
  if (!name) return null;
  if (!hosts.has(name)) hosts.set(name, {name, metrics:{}, disks:new Map(), rx:[], tx:[], problems:[], os:null, version:null, ip:null, maintenance:null});
  return hosts.get(name);
};
function latest(field, time) {
  for (let i = (field.values?.length || 0)-1; i >= 0; i--) {
    const v = read(field,i);
    if (v !== null && v !== undefined && v !== '' && Number.isFinite(Number(v))) {
      let stamp=time ? Number(read(time,i)) : null;
      if(stamp!==null && stamp>0 && stamp<100000000000) stamp*=1000;
      return {value:Number(v),time:stamp};
    }
  }
  return {value:null,time:null};
}
for (const frame of frames) {
  const fields = frame.fields || [];
  const hf = fields.find(f=>f.name==='Host');
  if (hf) {
    const kf = fields.find(f=>f.name==='Key');
    const vf = fields.find(f=>f.name==='Last value');
    for(let i=0;i<(hf.values?.length||0);i++) {
      const h=host(read(hf,i)); if(!h) continue;
      const key=String(read(kf,i)||''); const v=read(vf,i);
      if(v===null || v===undefined || v==='') continue;
      if(/^system\.sw\.os(?:\[name\])?$/.test(key)) h.os=String(v);
      else if(key==='system.uname' && !h.os) h.os=String(v);
      else if(key==='agent.version') h.version=String(v);
      else if(key==='system.hostname') h.hostname=String(v);
      else if(key==='system.hw.macaddr') h.mac=String(v);
    }
    continue;
  }
  if(frame.refId==='P') {
    const pf=fields.find(f=>f.name==='Problems');
    for(let i=0;i<(pf?.values?.length||0);i++) {
      const p=read(pf,i); if(!p || typeof p!=='object') continue;
      for(const ph of p.hosts||[]) {
        const h=host(ph.name||ph.host); if(!h) continue;
        if(!h.problems.some(x=>x.eventid===p.eventid)) h.problems.push(p);
        if(ph.maintenance_status!==undefined) h.maintenance=Number(ph.maintenance_status)===1;
        if(ph.hostIp) h.ip=ph.hostIp;
        else if(ph.ip) h.ip=ph.ip;
        else if(p.hostIP) h.ip=p.hostIP;
      }
    }
    continue;
  }
  const tf=fields.find(f=>f.type==='time');
  for(const f of fields.filter(f=>f.type==='number')) {
    const scope=f.config?.custom?.scopedVars || {};
    const nativeHost=f.labels?.host || scope.__zbx_host_name?.value || scope.__zbx_host?.value;
    const nativeItem=f.labels?.item || scope.__zbx_item?.value || scope.__zbx_item_name?.value;
    const nativeKey=f.labels?.item_key || scope.__zbx_item_key?.value;
    const metricByRef={A_CPU:'CPU utilization',A_RAM:'Memory utilization',A_CORES:'Number of cores',A_TOTAL:'Total memory',A_PING:'Zabbix agent ping',A_UPTIME:'Uptime'};
    const forcedMetric=metricByRef[frame.refId];
    let meta=nativeHost && (forcedMetric || nativeItem || nativeKey) ? {Servidor:String(nativeHost),Metrica:String(forcedMetric || nativeItem || nativeKey)} : null;
    for(const name of [f.config?.displayNameFromDS,f.config?.displayName,frame.name,f.name]) {
      if(meta) break;
      try {const m=JSON.parse(name); if(m.Servidor && m.Metrica && !String(m.Servidor).includes('$')) {meta=m;break;}} catch(e) {}
    }
    if(!meta && frame.name) {
      const name=String(frame.name);
      const known=[...hosts.keys()].sort((a,b)=>b.length-a.length).find(h=>name.startsWith(h+': '));
      if(known) meta={Servidor:known,Metrica:name.slice(known.length+2)};
    }
    if(!meta) continue;
    if(forcedMetric) meta.Metrica=forcedMetric;
    if(frame.refId==='C') meta.Metrica='RED RECIBIDA (bit/s)';
    if(frame.refId==='D') meta.Metrica='RED ENVIADA (bit/s)';
    if(frame.refId==='B' && nativeKey) meta.Metrica=String(nativeKey);
    const h=host(meta.Servidor), m=meta.Metrica, v=latest(f,tf);
    if(m==='RED RECIBIDA (bit/s)') h.rx.push(v);
    else if(m==='RED ENVIADA (bit/s)') h.tx.push(v);
    else if(/^vfs\.fs\.(?:dependent\.)?size\[/.test(m)) {
      const disk=m.match(/^vfs\.fs\.(?:dependent\.)?size\[([^,]+),pused\]$/);
      if(disk) h.disks.set(disk[1],v);
    } else if(frame.refId==='B') {
      const disk=String(nativeItem||m).match(/\(([A-Za-z]:)\)/) || String(nativeItem||m).match(/\[([^\]]+)\]/);
      if(disk) h.disks.set(disk[1],v);
    } else h.metrics[m]=v;
  }
}
const fresh = v => v && v.value!==null && v.time!==null && end-v.time <= MAX_AGE && v.time<=end;
const num = (h,k,staticValue=false) => {const v=h.metrics[k]; return staticValue ? v?.value ?? null : fresh(v) ? v.value : null;};
const level = n => n===null ? 'missing' : n>=90 ? 'critical' : n>=75 ? 'warning' : 'normal';
const pct = n => n===null ? '—' : n.toFixed(1)+'%';
const bar = n => `<div class="zr-meter"><div class="zr-track"><span class="${level(n)}" style="width:${n===null?0:Math.min(100,Math.max(0,n))}%"></span></div><b>${pct(n)}</b></div>`;
const rate = vs => {
  if(!vs.length || vs.some(v=>!fresh(v))) return '—';
  let n=vs.reduce((s,v)=>s+v.value,0), u=0; const units=['bit/s','kbit/s','Mbit/s','Gbit/s'];
  while(n>=1000&&u<3){n/=1000;u++;} return n.toFixed(1)+' '+units[u];
};
const uptime = n => n===null ? '—' : `${Math.floor(n/86400)}d ${Math.floor(n%86400/3600)}h ${Math.floor(n%3600/60)}m`;
function evaluateHost(h) {
  h.cpu=num(h,'CPU utilization');h.ram=num(h,'Memory utilization');
  h.family=h.os ? (/windows/i.test(h.os)?'Windows':/linux|ubuntu|debian|rocky|centos|alma|red hat|suse|fedora/i.test(h.os)?'Linux':'Otros') : 'Sin SO';
  const severity=Math.max(-1,...h.problems.map(p=>Number(p.severity)));
  const values=[h.cpu,h.ram,...[...h.disks.values()].filter(fresh).map(v=>v.value)];
  h.problemState=severity>=3?'critical':severity===2?'warning':'normal';
  h.state=h.maintenance===true?'maintenance':severity>=3||values.some(v=>v!==null&&v>=90)?'critical':severity===2||values.some(v=>v!==null&&v>=75)?'warning':h.cpu===null&&h.ram===null?'missing':'normal';
  h.online=fresh(h.metrics['Zabbix agent ping']) && h.metrics['Zabbix agent ping'].value===1;
  return h;
}
let rows = [...hosts.values()].map(evaluateHost);
let scopeReady=false, scopeError=false;
const labels={normal:'Normal',warning:'Advertencia',critical:'Crítico',missing:'Sin datos',maintenance:'Mantenimiento'};
const counters=[['total',rows.length,'TOTAL'],['normal',rows.filter(h=>h.online).length,'AGENTE CON DATOS'],['warning',rows.filter(h=>h.state==='warning').length,'ADVERTENCIAS'],['critical',rows.filter(h=>h.state==='critical').length,'CRÍTICOS'],['missing',rows.filter(h=>h.state==='missing').length,'SIN DATOS']];
root.innerHTML=`<div class="zr"><div class="laka-bar"><div class="zr-heading">Recursos de servidores <small>V1.0 · Agentes Windows y Linux</small></div><div class="laka-brand"><strong>LAKA</strong><span>Soluciones Tecnológicas</span></div></div><div class="zr-summary">${counters.map(([c,n,t])=>`<div class="zr-card ${c}"><b>…</b><span>${t}</span></div>`).join('')}</div><div class="zr-toolbar"><input class="zr-search" aria-label="Buscar servidor" placeholder="Buscar servidor, IP o sistema operativo…"><span class="zr-count"></span><div class="zr-filters">${[['all','Todos'],['critical','Críticos'],['warning','Advertencias'],['missing','Sin datos'],['maintenance','Mantenimiento'],['Windows','Windows'],['Linux','Linux']].map(([k,t])=>`<button type="button" data-filter="${k}">${t}</button>`).join('')}</div></div><div class="zr-scroll"><table><thead><tr>${[['state','ESTADO'],['name','SERVIDOR'],['cpu','CPU USADA'],['cores','vCPU'],['ram','RAM USADA'],['total','RAM TOTAL'],['disks','DISCOS · USADO'],['network','RED · RECIBIDA / ENVIADA'],['os','SISTEMA OPERATIVO'],['problems','PROBLEMAS'],['uptime','TIEMPO ACTIVO']].map(([k,t])=>`<th data-sort="${k}">${t} ↕</th>`).join('')}</tr></thead><tbody></tbody></table></div><div class="zr-note">CPU, RAM y discos: advertencia ≥75%, crítico ≥90%. Problemas: severidad Zabbix. «—»: sin lectura válida o reciente (15 min). Red: suma de interfaces consultadas; puede incluir interfaces virtuales. Mantenimiento solo se identifica si viene informado en un problema.</div></div>`;
const ui=root.zrUiState ||= {filter:'all',search:'',sort:'name',direction:1};
let {filter,search,sort,direction}=ui;
root.querySelector('.zr-search').value=search;
const range=context.grafana.timeRange;
const detail=h=> {
  const url=`/d/zbx-win-agent-detail-plugin-v2/windows-detalle-zabbix?var-host=${encodeURIComponent(h.name)}&from=${Number(range.from.valueOf())}&to=${end}`;
  const path=context.grafana.replaceVariables('${__appSubUrl}');
  return path && !path.includes('$') ? path+url : url;
};
function draw() {
  const scopedRows=scopeReady?rows:[];
  const counts=[scopedRows.length,scopedRows.filter(h=>h.online).length,scopedRows.filter(h=>h.state==='warning').length,scopedRows.filter(h=>h.state==='critical').length,scopedRows.filter(h=>h.state==='missing').length];
  root.querySelectorAll('.zr-card b').forEach((el,i)=>el.textContent=scopeReady?String(counts[i]):'…');
  const visible=scopedRows.filter(h=>(filter==='all'||h.state===filter||h.family===filter)&&[h.name,h.ip,h.os].join(' ').toLowerCase().includes(search));
  const sortValue=h=>sort==='cores'?num(h,'Number of cores',true):sort==='total'?num(h,'Total memory',true):sort==='uptime'?num(h,'Uptime'):sort==='problems'?h.problems.length:h[sort]??h.name;
  visible.sort((a,b)=>{const x=sortValue(a),y=sortValue(b);return direction*(typeof x==='number'&&typeof y==='number'?x-y:String(x??'').localeCompare(String(y??''),undefined,{numeric:true}));});
  root.querySelector('tbody').innerHTML=visible.map(h=> {
    const disks=[...h.disks.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([d,v])=>`<span class="zr-disk ${fresh(v)?level(v.value):'missing'}" title="${esc(d)} · espacio usado${v.time?' · '+esc(new Date(v.time).toLocaleString()):''}">${esc(d)} ${fresh(v)?v.value.toFixed(0)+'%':'—'}</span>`).join('')||'—';
    const total=num(h,'Total memory',true);
    const problemLabel=h.problems.length ? `${h.problems.length} activos` : frames.some(f=>f.refId==='P')&&!context.panelData.error&&!context.panelData.errors?.length?'Sin problemas':'Sin consulta';
    return `<tr><td><span class="zr-status ${h.state}">● ${labels[h.state]}</span></td><td class="zr-name"><a href="${esc(detail(h))}">${esc(h.name)}</a><small>${h.ip?esc(h.ip)+' · ':''}${h.version?'Agente '+esc(h.version):(h.metadataLoaded?'Versión sin valor disponible':'Consultando versión…')}</small></td><td>${bar(h.cpu)}</td><td>${num(h,'Number of cores',true)??'—'}</td><td>${bar(h.ram)}</td><td>${total===null?'—':(total/1073741824).toFixed(1)+' GiB'}</td><td><div class="zr-disks">${disks}</div></td><td class="zr-network"><span>↓ ${rate(h.rx)}</span><span>↑ ${rate(h.tx)}</span></td><td class="zr-os" title="${esc(h.os||'')}"><span class="zr-badge">${esc(h.family)}</span><span>${esc(h.os||(h.metadataLoaded?'SO sin valor disponible':'Consultando sistema operativo…'))}</span></td><td><span class="zr-pill ${h.problemState}" title="${esc(h.problems.map(p=>p.name||p.description).join('\n'))}">${problemLabel}</span></td><td>${uptime(num(h,'Uptime'))}</td></tr>`;
  }).join('') || `<tr><td colspan="11">${scopeError?'No se pudo verificar las plantillas de los hosts. Actualice el panel.':!scopeReady?'Verificando servidores con agente Windows o Linux…':'No hay servidores con las plantillas de agente Windows o Linux que coincidan con la selección.'}</td></tr>`;
  root.querySelector('.zr-count').textContent=`${visible.length} servidores`;
  root.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));
}
// Delegación en el contenedor: los eventos sobreviven al reemplazo de su HTML.
if(root.zrClickHandler) root.removeEventListener('click',root.zrClickHandler,true);
if(root.zrInputHandler) root.removeEventListener('input',root.zrInputHandler,true);
root.zrClickHandler=e=> {
  const button=e.target.closest?.('button[data-filter]');
  const header=e.target.closest?.('th[data-sort]');
  if(button && root.contains(button)) {e.preventDefault();filter=button.dataset.filter;}
  else if(header && root.contains(header)) {direction=sort===header.dataset.sort?-direction:1;sort=header.dataset.sort;}
  else return;
  Object.assign(ui,{filter,search,sort,direction});draw();
};
root.zrInputHandler=e=> {
  if(!e.target.matches?.('.zr-search') || !root.contains(e.target)) return;
  search=e.target.value.toLowerCase();Object.assign(ui,{filter,search,sort,direction});draw();
};
root.addEventListener('click',root.zrClickHandler,true);
root.addEventListener('input',root.zrInputHandler,true);

draw();

// Metadatos de cambio poco frecuente: último valor del item, independiente del rango.
// Usa el proxy autenticado del datasource; no contiene credenciales de Zabbix.
const metadataToken = {};
root.zrMetadataToken = metadataToken;
const selectedNames = rows.map(h=>h.name).sort();
const requestTargets = context.panelData.request?.targets || [];
const metadataUid = requestTargets.map(t=>t.datasource?.uid).find(u=>u && !u.includes('$')) || context.grafana.replaceVariables('${DS_ZABBIX}');
const subUrlValue = context.grafana.replaceVariables('${__appSubUrl}');
const metadataBase = subUrlValue && !subUrlValue.includes('$') ? subUrlValue : '';
function applyMetadata(result) {
  const {items,selected}=result;
  if(root.zrMetadataToken !== metadataToken) return;
  const allowed=new Set(selected.flatMap(h=>[h.name,h.host]));
  rows=rows.filter(h=>allowed.has(h.name));
  scopeReady=true;
  for(const h of rows) {
    h.metadataLoaded=true;
    const own=items.filter(i=>(i.hosts||[]).some(x=>x.name===h.name||x.host===h.name));
    const last=key=>own.find(i=>i.key_===key && Number(i.lastclock)>0 && i.lastvalue!==undefined && i.lastvalue!=='')?.lastvalue;
    h.os=last('system.sw.os[name]') || last('system.sw.os') || last('system.uname') || h.os;
    h.version=last('agent.version') || h.version;
    // Recuperación numérica por clave: los nombres de ítems varían por plantilla.
    const numeric=(keys,invert=false)=> {
      const values=own.filter(i=>keys.includes(i.key_) && Number(i.lastclock)>0 && i.lastvalue!=='' && Number.isFinite(Number(i.lastvalue)))
        .map(i=>({value:invert?100-Number(i.lastvalue):Number(i.lastvalue),time:Number(i.lastclock)*1000})).filter(fresh);
      return values.sort((a,b)=>b.time-a.time)[0];
    };
    const fallback={
      'CPU utilization':numeric(['system.cpu.util']) || numeric(['system.cpu.util[,idle]'],true),
      'Memory utilization':numeric(['vm.memory.utilization','vm.memory.util','vm.memory.size[pused]']) || numeric(['vm.memory.size[pavailable]'],true) || (()=> {
        const available=numeric(['vm.memory.size[available]']);
        const total=own.find(i=>i.key_==='vm.memory.size[total]' && Number(i.lastclock)>0 && Number(i.lastvalue)>0);
        return available && total && available.value>=0 && available.value<=Number(total.lastvalue)
          ? {value:100*(1-available.value/Number(total.lastvalue)),time:available.time} : undefined;
      })(),
      'Uptime':numeric(['system.uptime']),
      'Zabbix agent ping':numeric(['agent.ping'])
    };
    for(const [metric,value] of Object.entries(fallback)) {
      const existing=h.metrics[metric];
      if(value && (!fresh(existing) || value.time>=existing.time)) h.metrics[metric]=value;
    }

    for(const [key,metric] of [['system.cpu.num','Number of cores'],['vm.memory.size[total]','Total memory']]) {
      const item=own.find(i=>i.key_===key && Number(i.lastclock)>0 && Number.isFinite(Number(i.lastvalue)));
      if(item) h.metrics[metric]={value:Number(item.lastvalue),time:Number(item.lastclock)*1000};
    }
    h.family=h.os ? (/windows/i.test(h.os)?'Windows':/linux|ubuntu|debian|rocky|centos|alma|red hat|suse|fedora/i.test(h.os)?'Linux':'Otros') : 'Sin SO';
    evaluateHost(h);
  }
  draw();
  root.querySelectorAll('.zr-name small').forEach(el=>{if(el.textContent==='Consultando versión…') el.textContent='Versión sin valor disponible';});
  root.querySelectorAll('.zr-os>span+span').forEach(el=>{if(el.textContent==='Consultando sistema operativo…') el.textContent='SO sin valor disponible';});
}
async function loadMetadata() {
  if(!selectedNames.length) {scopeReady=true;draw();return;}
  if(!metadataUid || metadataUid.includes('$')) throw new Error('No se pudo resolver el datasource Zabbix.');
    const api=async(method,params)=> {
      const response=await fetch(metadataBase+'/api/datasources/uid/'+encodeURIComponent(metadataUid)+'/resources/zabbix-api',{
        method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({method,params}),signal:AbortSignal.timeout(20000)
      });
      if(!response.ok) throw new Error('Consulta de metadatos: HTTP '+response.status);
      const result=await response.json();
      if(result.error) throw new Error('Zabbix no pudo devolver los metadatos.');
      if(!Array.isArray(result.result)) throw new Error('Respuesta de metadatos inesperada.');
      return result.result;
    };
  const cache=globalThis.__lakaZbxMetadataCache ||= new Map();
  const cacheKey=JSON.stringify(['agent-keys-v39',metadataBase,metadataUid,selectedNames]);
  let entry=cache.get(cacheKey);
  if(!entry || Date.now()-entry.created>60*1000) {
    entry={created:Date.now(),promise:(async()=> {
      const candidates=await api('host.get',{output:['hostid','host','name'],selectParentTemplates:['host','name'],filter:{name:selectedNames}});
      const supported=new Set(['Windows by Zabbix agent','Windows by Zabbix agent active','Linux by Zabbix agent','Linux by Zabbix agent active']);
      const selected=candidates.filter(h=>(h.parentTemplates||[]).some(t=>supported.has(t.host)||supported.has(t.name)));
      if(!selected.length) return {selected,items:[]};
      const items=await api('item.get',{output:['itemid','key_','lastvalue','lastclock','value_type'],hostids:selected.map(h=>h.hostid),
        selectHosts:['hostid','host','name'],filter:{status:0,key_:['agent.version','system.sw.os[name]','system.sw.os','system.uname','system.cpu.num','vm.memory.size[total]','system.cpu.util','system.cpu.util[,idle]','vm.memory.utilization','vm.memory.util','vm.memory.size[pused]','vm.memory.size[pavailable]','vm.memory.size[available]','system.uptime','agent.ping']}});
      return {selected,items};
    })()};
    cache.set(cacheKey,entry);
    if(cache.size>20) cache.delete(cache.keys().next().value);
    entry.promise.catch(()=>{if(cache.get(cacheKey)===entry)cache.delete(cacheKey);});
  }
  const result=await entry.promise;
  if(root.zrMetadataToken!==metadataToken) return;
  // Último valor de Zabbix puede ser posterior al período absoluto de Grafana.
  // Recuperar únicamente métricas ausentes y dentro de los últimos 15 min del período.
  const keys={
    'system.cpu.util':'CPU utilization','system.cpu.util[,idle]':'CPU utilization',
    'vm.memory.utilization':'Memory utilization','vm.memory.util':'Memory utilization',
    'vm.memory.size[pused]':'Memory utilization','vm.memory.size[pavailable]':'Memory utilization',
    'vm.memory.size[available]':'Memory utilization','system.uptime':'Uptime','agent.ping':'Zabbix agent ping'
  };
  const from=Math.ceil(Math.max(Number(context.grafana.timeRange.from.valueOf()),end-MAX_AGE)/1000);
  const till=Math.floor(end/1000);
  const missing=result.items.filter(i=> {
    const metric=keys[i.key_];
    const h=rows.find(h=>(i.hosts||[]).some(x=>x.name===h.name||x.host===h.name));
    return metric && h && !fresh(h.metrics[metric]) && Number(i.lastclock)>till;
  });
  const replacements=new Map();
  let next=0,historyFailed=false;
  // Concurrencia acotada y una sola muestra por ítem; caché también por período.
  await Promise.all(Array.from({length:Math.min(3,missing.length)},async()=> {
    while(next<missing.length) {
      const item=missing[next++];
      const key=JSON.stringify(['history-v39',metadataBase,metadataUid,item.itemid,from,till]);
      let sample=cache.get(key);
      if(!sample || Date.now()-sample.created>60000) {
        const type=Number(item.value_type ?? (/system.uptime|agent.ping|size\[available\]/.test(item.key_)?3:0));
        sample={created:Date.now(),promise:api('history.get',{
          output:['itemid','clock','value'],history:type,itemids:[item.itemid],
          time_from:from,time_till:till,sortfield:['clock','ns'],sortorder:'DESC',limit:1
        })};
        cache.set(key,sample);
        if(cache.size>200) cache.delete(cache.keys().next().value);
        sample.promise.catch(()=>{if(cache.get(key)===sample)cache.delete(key);});
      }
      try {
        const [value]=await sample.promise;
        if(value) replacements.set(item.itemid,{...item,lastvalue:value.value,lastclock:value.clock});
      } catch(error) {historyFailed=true;}
    }
  }));
  applyMetadata({...result,items:result.items.map(i=>replacements.get(i.itemid)||i)});
  if(historyFailed && root.zrMetadataToken===metadataToken) {
    const note=root.querySelector('.zr-note');
    if(note) note.textContent+=' No se pudo recuperar alguna métrica histórica; pruebe Últimas 2 horas.';
  }
}
loadMetadata().catch(()=> {
  if(root.zrMetadataToken!==metadataToken) return;
  scopeError=true;draw();
  root.querySelectorAll('.zr-name small').forEach(el=>{if(el.textContent==='Consultando versión…') el.textContent='Versión: error de consulta';});
  root.querySelectorAll('.zr-os>span+span').forEach(el=>{if(el.textContent==='Consultando sistema operativo…') el.textContent='SO: error de consulta';});
  const note=root.querySelector('.zr-note');
  if(note) note.textContent+=' No se pudieron consultar los metadatos del agente mediante el datasource Zabbix.';
});

