.zr { background:#181b1f;color:#d8dee9;font:12px Arial,sans-serif;padding:12px;box-sizing:border-box; }
.zr * { box-sizing:border-box; }
.zr .zr-heading {font-size:16px;font-weight:700;margin-bottom:16px}.zr .zr-heading small{font-size:11px;font-weight:400;margin-left:12px;color:#9ba7b7}
.zr .zr-summary{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:12px}.zr .zr-card{display:flex;align-items:center;gap:12px;background:#20242b;border:1px solid #353b45;border-left:4px solid #2dd4bf;border-radius:5px;padding:10px}.zr .zr-card b{font-size:24px}.zr .zr-card span{font-size:10px}
.zr .zr-card.warning{border-left-color:#f5b942}.zr .zr-card.critical{border-left-color:#ff6685}.zr .zr-card.missing{border-left-color:#94a3b8}
.zr .zr-toolbar{display:flex;gap:12px;align-items:center;margin-bottom:12px;flex-wrap:wrap}.zr .zr-search{width:340px;max-width:100%;border:1px solid #454d59;border-radius:4px;padding:9px;background:#181b1f;color:#d8dee9}.zr .zr-count{border-radius:16px;background:#2b313b;padding:5px 9px;font-size:11px}.zr .zr-filters{margin-left:auto;display:flex;gap:5px;flex-wrap:wrap}.zr button{border:1px solid #424a56;background:#252a32;color:#d8dee9;border-radius:4px;padding:7px 10px;cursor:pointer;font-size:11px}.zr button.active{background:#183c3a;border-color:#2dd4bf}
.zr .zr-scroll{overflow:auto;border:1px solid #353c46;border-radius:5px}.zr table{width:100%;border-collapse:collapse;white-space:nowrap}.zr th{padding:10px 10px;background:#242b35;text-align:left;font-size:10px;font-weight:600;color:#b9c6d9;cursor:pointer;position:sticky;top:0;z-index:1}.zr td{padding:6px 10px;border-top:1px solid #303641;vertical-align:middle}.zr tr:hover td{background:#222d38}.zr .zr-name{min-width:180px;max-width:310px}.zr .zr-name a{color:#d8dee9;font-weight:700;text-decoration:none}.zr .zr-name a:hover{text-decoration:underline;color:#5ce4cd}.zr .zr-name small{display:block;margin-top:3px;color:#9aa9ba;font-size:10px}
.zr .zr-meter{display:flex;gap:9px;align-items:center;min-width:155px}.zr .zr-meter b{font-size:11px;font-weight:400;min-width:42px;text-align:right}.zr .zr-track{width:110px;height:14px;background:#11151b;border:1px solid #424d5d;border-radius:2px;overflow:hidden}.zr .zr-track span{display:block;height:100%;background:linear-gradient(#4bdcc2,#00b39d)}.zr .zr-track span.warning{background:linear-gradient(#ffd86e,#eda710)}.zr .zr-track span.critical{background:linear-gradient(#ff92a6,#eb3b60)}
.zr .zr-status{font-weight:600;font-size:11px}.zr .normal{color:#3de0b9}.zr .warning{color:#ffc857}.zr .critical{color:#ff6b89}.zr .missing{color:#9ba7b7}.zr .maintenance{color:#75baff}
.zr .zr-disks{display:flex;gap:4px;flex-wrap:wrap;max-width:300px;min-width:130px}.zr .zr-disk{border:1px solid #454f5f;background:#20242b;border-radius:3px;padding:3px 6px;color:#d8dee9;font-size:10px;font-weight:700}.zr .zr-disk.warning{border-color:#c99635;background:#3a301b}.zr .zr-disk.critical{border-color:#d85b74;background:#3d202c}.zr .zr-disk.missing{color:#9ba7b7}
.zr .zr-network span{display:block;margin:2px 0;font-size:11px;color:#66d4f5}.zr .zr-network span+span{color:#b9a0ff}.zr .zr-os{max-width:260px}.zr .zr-os>span+span{display:inline-block;max-width:185px;overflow:hidden;text-overflow:ellipsis;vertical-align:middle;font-size:11px}.zr .zr-badge{background:#2469a2;color:white;border-radius:3px;padding:5px;font-size:9px;margin-right:5px}.zr .zr-pill{display:inline-block;border-radius:20px;padding:4px 8px;font-size:10px;background:#183b35}.zr .zr-pill.critical{background:#40232f}.zr .zr-pill.warning{background:#40331e}.zr .zr-note{margin-top:12px;font-size:10px;color:#9aa9ba;line-height:1.5}
@media(max-width:900px){.zr .zr-summary{grid-template-columns:repeat(3,1fr)}.zr .zr-filters{margin-left:0}}

.zr .zr-search::placeholder {color:#91a0b5;opacity:1}
.zr .zr-search:focus {outline:2px solid #5794f2;outline-offset:1px}
.zr button:hover {background:#333c49;border-color:#697c97}
.zr button.active {color:#6ae9d1}
.zr .zr-card.total {color:#d8dee9}
.zr .zr-card.normal {color:#3de0b9}
.zr .zr-disk.warning {color:#ffcf66}
.zr .zr-disk.critical {color:#ff8ca3}
.zr .zr-scroll {scrollbar-color:#4b5667 #181b1f}
.zr .zr-name a:focus-visible,.zr button:focus-visible {outline:2px solid #5794f2;outline-offset:3px}

.zr td {line-height:1.25}

/* Identidad visual: LAKA Soluciones Tecnológicas */
.laka-bar{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:12px;flex-wrap:wrap}.laka-bar .zr-heading{margin-bottom:0}.laka-brand{display:flex;align-items:center;gap:9px;color:#b9c6d9;font-size:11px;white-space:nowrap}.laka-brand strong{font-size:19px;letter-spacing:2px;color:#2dd4bf;border-right:1px solid #454d59;padding-right:9px}
